from __future__ import annotations

import ast
import subprocess
import sys
from pathlib import Path

MODULE = '"""\nOIA-011\nOracle Forward Shadow Performance Aggregator\n\nReads immutable OIA-010 fixed-horizon outcome artifacts and produces deterministic\nresearch-performance summaries. It never changes outcome artifacts, OIA-009 ledger\nentries, canonical PostgreSQL observations, Q Series state, orders, funds, or portfolios.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport os\nimport tempfile\nfrom dataclasses import asdict, dataclass, is_dataclass\nfrom datetime import datetime, timezone\nfrom decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN\nfrom pathlib import Path\nfrom statistics import median\nfrom types import MappingProxyType\nfrom typing import Any, Iterable, Mapping, Optional\n\nfrom .oracle_forward_shadow_outcome_evaluator import (\n    DEFAULT_OUTCOME_DIRECTORY,\n    FLAT,\n    GRADED,\n    LOSS,\n    WIN,\n    stable_hash as outcome_stable_hash,\n)\n\nSCHEMA_VERSION = "OIA-011"\nENGINE_ID = "OIA-011"\nREAD_ONLY_CORPUS = True\nEXECUTION_ALLOWED = False\nALERTS_ALLOWED = False\nQSERIES_HANDOFF_ALLOWED = False\nSIGNALS_ALLOWED = False\nTRADING_RECOMMENDATIONS_ALLOWED = False\nSOURCE_OUTCOME_MUTATION_ALLOWED = False\nPERFORMANCE_ARTIFACT_PERSISTENCE_ALLOWED = True\nDEFAULT_PERFORMANCE_DIRECTORY = Path("runtime") / "oracle_intelligence" / "forward_shadow_performance"\nAGGREGATION_DIMENSIONS = ("overall", "horizon", "market_horizon", "family_horizon", "direction_horizon")\n_QUANT = Decimal("0.00000001")\n\n\nclass ForwardShadowPerformanceError(RuntimeError):\n    pass\n\n\nclass ForwardShadowPerformanceInvariantError(ForwardShadowPerformanceError):\n    pass\n\n\ndef _aware_utc(value: datetime, name: str) -> datetime:\n    if not isinstance(value, datetime) or value.tzinfo is None or value.utcoffset() is None:\n        raise ForwardShadowPerformanceInvariantError(f"{name} must be timezone-aware.")\n    return value.astimezone(timezone.utc)\n\n\ndef _canonical(value: Any) -> Any:\n    if is_dataclass(value):\n        return _canonical(asdict(value))\n    if isinstance(value, Mapping):\n        return {str(k): _canonical(v) for k, v in value.items()}\n    if isinstance(value, (list, tuple)):\n        return [_canonical(v) for v in value]\n    if isinstance(value, datetime):\n        return _aware_utc(value, "datetime").isoformat()\n    if isinstance(value, Decimal):\n        return format(value, "f")\n    return value\n\n\ndef stable_hash(value: Any) -> str:\n    payload = json.dumps(_canonical(value), sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)\n    return hashlib.sha256(payload.encode("utf-8")).hexdigest()\n\n\ndef _freeze(value: Mapping[str, Any]) -> Mapping[str, Any]:\n    return MappingProxyType(dict(value))\n\n\ndef _decimal(value: Any, name: str) -> Decimal:\n    try:\n        result = Decimal(str(value))\n    except (InvalidOperation, ValueError, TypeError) as exc:\n        raise ForwardShadowPerformanceInvariantError(f"{name} must be a finite decimal.") from exc\n    if not result.is_finite():\n        raise ForwardShadowPerformanceInvariantError(f"{name} must be a finite decimal.")\n    return result\n\n\ndef _ratio(numerator: int, denominator: int) -> str:\n    if denominator <= 0:\n        return "0.00000000"\n    return format((Decimal(numerator) / Decimal(denominator)).quantize(_QUANT, rounding=ROUND_HALF_EVEN), "f")\n\n\ndef _mean(values: list[Decimal]) -> str:\n    if not values:\n        return "0.00000000"\n    return format((sum(values, Decimal("0")) / Decimal(len(values))).quantize(_QUANT, rounding=ROUND_HALF_EVEN), "f")\n\n\ndef _median(values: list[Decimal]) -> str:\n    if not values:\n        return "0.00000000"\n    return format(Decimal(str(median(values))).quantize(_QUANT, rounding=ROUND_HALF_EVEN), "f")\n\n\ndef _atomic_json_write(path: Path, payload: Mapping[str, Any]) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    serialized = json.dumps(_canonical(payload), sort_keys=True, indent=2, ensure_ascii=False) + "\\n"\n    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", newline="\\n", delete=False, dir=str(path.parent), prefix=f".{path.name}.", suffix=".tmp")\n    temporary = Path(handle.name)\n    try:\n        with handle:\n            handle.write(serialized)\n            handle.flush()\n            os.fsync(handle.fileno())\n        os.replace(temporary, path)\n    finally:\n        if temporary.exists():\n            temporary.unlink()\n\n\n@dataclass(frozen=True)\nclass OracleForwardShadowPerformanceBucket:\n    dimension: str\n    key: str\n    graded_count: int\n    win_count: int\n    loss_count: int\n    flat_count: int\n    decisive_count: int\n    win_rate: str\n    loss_rate: str\n    flat_rate: str\n    mean_directional_return: str\n    median_directional_return: str\n    positive_return_rate: str\n    bucket_hash: str\n\n    def to_dict(self) -> Mapping[str, Any]:\n        return _freeze(_canonical(asdict(self)))\n\n\n@dataclass(frozen=True)\nclass OracleForwardShadowPerformanceReport:\n    schema_version: str\n    engine_id: str\n    generated_at: datetime\n    source_outcome_directory: str\n    performance_directory: str\n    source_artifact_count: int\n    verified_graded_outcome_count: int\n    duplicate_outcome_count: int\n    bucket_count: int\n    buckets: tuple[OracleForwardShadowPerformanceBucket, ...]\n    source_outcome_hashes: tuple[str, ...]\n    read_only_corpus: bool\n    execution_allowed: bool\n    alerts_allowed: bool\n    qseries_handoff_allowed: bool\n    signals_allowed: bool\n    trading_recommendations_allowed: bool\n    source_outcome_mutation_allowed: bool\n    performance_artifact_persistence_allowed: bool\n    report_hash: str\n\n    def to_dict(self) -> Mapping[str, Any]:\n        return _freeze(_canonical(asdict(self)))\n\n\nclass OracleForwardShadowPerformanceAggregator:\n    read_only_corpus = True\n    execution_allowed = False\n    alerts_allowed = False\n    qseries_handoff_allowed = False\n    signals_allowed = False\n    trading_recommendations_allowed = False\n    source_outcome_mutation_allowed = False\n    performance_artifact_persistence_allowed = True\n\n    def __init__(self, *, outcome_directory: Path | str = DEFAULT_OUTCOME_DIRECTORY, performance_directory: Path | str = DEFAULT_PERFORMANCE_DIRECTORY) -> None:\n        self._outcome_directory = Path(outcome_directory)\n        self._performance_directory = Path(performance_directory)\n\n    def _load_outcomes(self) -> tuple[list[Mapping[str, Any]], int, int]:\n        root = self._outcome_directory / "outcomes"\n        files = sorted(root.glob("*/*.json")) if root.exists() else []\n        outcomes: list[Mapping[str, Any]] = []\n        seen: set[tuple[str, int]] = set()\n        duplicates = 0\n        for path in files:\n            payload = json.loads(path.read_text(encoding="utf-8"))\n            if payload.get("schema_version") != "OIA-010" or payload.get("engine_id") != "OIA-010":\n                raise ForwardShadowPerformanceInvariantError(f"Unexpected outcome contract: {path}")\n            supplied = str(payload.get("outcome_hash", ""))\n            body = dict(payload)\n            body.pop("outcome_hash", None)\n            if len(supplied) != 64 or supplied != outcome_stable_hash(body):\n                raise ForwardShadowPerformanceInvariantError(f"Outcome hash verification failed: {path}")\n            if payload.get("status") != GRADED:\n                continue\n            grade = payload.get("grade")\n            if grade not in {WIN, LOSS, FLAT}:\n                raise ForwardShadowPerformanceInvariantError(f"Invalid grade in {path}")\n            key = (str(payload.get("evaluation_id", "")), int(payload.get("horizon_seconds", 0)))\n            if not key[0] or key[1] <= 0:\n                raise ForwardShadowPerformanceInvariantError(f"Invalid evaluation identity in {path}")\n            if key in seen:\n                duplicates += 1\n                continue\n            seen.add(key)\n            _decimal(payload.get("directional_return"), "directional_return")\n            outcomes.append(payload)\n        return outcomes, len(files), duplicates\n\n    @staticmethod\n    def _keys(payload: Mapping[str, Any]) -> tuple[tuple[str, str], ...]:\n        horizon = str(int(payload["horizon_seconds"]))\n        market = str(payload.get("market_id", ""))\n        family = str(payload.get("candidate_family", ""))\n        direction = str(payload.get("research_direction", ""))\n        return (\n            ("overall", "all"),\n            ("horizon", horizon),\n            ("market_horizon", f"{market}|{horizon}"),\n            ("family_horizon", f"{family}|{horizon}"),\n            ("direction_horizon", f"{direction}|{horizon}"),\n        )\n\n    def aggregate(self, *, generated_at: Optional[datetime] = None, persist: bool = True) -> OracleForwardShadowPerformanceReport:\n        anchor = _aware_utc(generated_at or datetime.now(timezone.utc), "generated_at")\n        outcomes, artifact_count, duplicates = self._load_outcomes()\n        groups: dict[tuple[str, str], list[Mapping[str, Any]]] = {}\n        for outcome in outcomes:\n            for key in self._keys(outcome):\n                groups.setdefault(key, []).append(outcome)\n        buckets: list[OracleForwardShadowPerformanceBucket] = []\n        for (dimension, key), items in sorted(groups.items()):\n            grades = [str(item["grade"]) for item in items]\n            returns = [_decimal(item["directional_return"], "directional_return") for item in items]\n            wins = grades.count(WIN); losses = grades.count(LOSS); flats = grades.count(FLAT)\n            decisive = wins + losses\n            positive = sum(1 for value in returns if value > 0)\n            body = {\n                "dimension": dimension,\n                "key": key,\n                "graded_count": len(items),\n                "win_count": wins,\n                "loss_count": losses,\n                "flat_count": flats,\n                "decisive_count": decisive,\n                "win_rate": _ratio(wins, decisive),\n                "loss_rate": _ratio(losses, decisive),\n                "flat_rate": _ratio(flats, len(items)),\n                "mean_directional_return": _mean(returns),\n                "median_directional_return": _median(returns),\n                "positive_return_rate": _ratio(positive, len(items)),\n            }\n            buckets.append(OracleForwardShadowPerformanceBucket(**body, bucket_hash=stable_hash(body)))\n        body = {\n            "schema_version": SCHEMA_VERSION,\n            "engine_id": ENGINE_ID,\n            "generated_at": anchor,\n            "source_outcome_directory": str(self._outcome_directory),\n            "performance_directory": str(self._performance_directory),\n            "source_artifact_count": artifact_count,\n            "verified_graded_outcome_count": len(outcomes),\n            "duplicate_outcome_count": duplicates,\n            "bucket_count": len(buckets),\n            "buckets": tuple(buckets),\n            "source_outcome_hashes": tuple(sorted(str(item["outcome_hash"]) for item in outcomes)),\n            "read_only_corpus": True,\n            "execution_allowed": False,\n            "alerts_allowed": False,\n            "qseries_handoff_allowed": False,\n            "signals_allowed": False,\n            "trading_recommendations_allowed": False,\n            "source_outcome_mutation_allowed": False,\n            "performance_artifact_persistence_allowed": True,\n        }\n        report = OracleForwardShadowPerformanceReport(**body, report_hash=stable_hash(body))\n        if persist:\n            _atomic_json_write(self._performance_directory / "current.json", report.to_dict())\n            history = self._performance_directory / "reports" / f"performance-{anchor.strftime(\'%Y%m%dT%H%M%S%fZ\')}-{report.report_hash[:16]}.json"\n            _atomic_json_write(history, report.to_dict())\n        return report\n\n\ndef _parser() -> argparse.ArgumentParser:\n    parser = argparse.ArgumentParser(description="Aggregate immutable OIA-010 forward-shadow outcomes.")\n    parser.add_argument("--outcome-directory", default=str(DEFAULT_OUTCOME_DIRECTORY))\n    parser.add_argument("--performance-directory", default=str(DEFAULT_PERFORMANCE_DIRECTORY))\n    parser.add_argument("--no-persist", action="store_true")\n    return parser\n\n\ndef main(argv: Optional[Iterable[str]] = None) -> int:\n    args = _parser().parse_args(list(argv) if argv is not None else None)\n    report = OracleForwardShadowPerformanceAggregator(outcome_directory=args.outcome_directory, performance_directory=args.performance_directory).aggregate(persist=not args.no_persist)\n    print("========================================")\n    print(" OIA-011 FORWARD SHADOW PERFORMANCE")\n    print("========================================")\n    print(f"[OK] Verified graded outcomes: {report.verified_graded_outcome_count}")\n    print(f"[OK] Performance buckets: {report.bucket_count}")\n    print(f"[OK] Report hash: {report.report_hash}")\n    print("[PASS] OIA-011 performance aggregation completed read-only")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
INIT = '"""Oracle Intelligence Analytics subsystem."""\n\nfrom .oracle_live_corpus_inspector import (\n    OracleCorpusMarketSummary,\n    OracleLiveCorpusInspector,\n    OracleLiveCorpusReport,\n)\nfrom .oracle_corpus_quality_analyzer import (\n    ACCEPTED,\n    QUARANTINED,\n    REJECTED,\n    OracleCorpusQualityAnalyzer,\n    OracleCorpusQualityReport,\n    OracleMarketQualityRecord,\n)\nfrom .oracle_market_statistics_engine import (\n    OracleMarketStatisticsEngine,\n    OracleMarketStatisticsRecord,\n    OracleMarketStatisticsReport,\n)\nfrom .oracle_market_feature_extraction_engine import (\n    OracleCanonicalMarketFeatureExtractionEngine,\n    OracleCanonicalMarketFeatureRecord,\n    OracleCanonicalMarketFeatureReport,\n)\nfrom .oracle_market_usefulness_scoring_engine import (\n    USEFUL,\n    WATCHLIST,\n    NOT_USEFUL,\n    OracleMarketUsefulnessRecord,\n    OracleMarketUsefulnessReport,\n    OracleMarketUsefulnessScoringEngine,\n)\nfrom .oracle_opportunity_candidate_generator import (\n    CANDIDATE,\n    EXCLUDED,\n    MOMENTUM_CONTINUATION,\n    VOLATILITY_REVERSION_WATCH,\n    OracleOpportunityCandidateGenerator,\n    OracleOpportunityCandidateRecord,\n    OracleOpportunityCandidateReport,\n)\nfrom .oracle_opportunity_admission_gate import (\n    ADMITTED,\n    DENIED,\n    NOT_CANDIDATE,\n    OracleOpportunityAdmissionGate,\n    OracleOpportunityAdmissionRecord,\n    OracleOpportunityAdmissionReport,\n)\n\nfrom .oracle_forward_shadow_evaluation_record_builder import (\n    PENDING,\n    OracleForwardShadowEvaluationRecordBuilder,\n    OracleForwardShadowEvaluationRecord,\n    OracleForwardShadowEvaluationReport,\n    OracleForwardShadowHorizon,\n)\n\nfrom .oracle_forward_shadow_evaluation_ledger import (\n    OracleForwardShadowEvaluationLedger,\n    OracleForwardShadowLedgerEntry,\n    OracleForwardShadowLedgerReport,\n)\n\nfrom .oracle_forward_shadow_outcome_evaluator import (\n    FLAT,\n    GRADED,\n    LOSS,\n    MATURED_NO_OBSERVATION,\n    WIN,\n    OracleForwardShadowHorizonOutcome,\n    OracleForwardShadowOutcomeEvaluationReport,\n    OracleForwardShadowOutcomeEvaluator,\n)\n\nfrom .oracle_forward_shadow_performance_aggregator import (\n    OracleForwardShadowPerformanceAggregator,\n    OracleForwardShadowPerformanceBucket,\n    OracleForwardShadowPerformanceReport,\n)\n\n__all__ = [\n    "OracleForwardShadowPerformanceAggregator",\n    "OracleForwardShadowPerformanceBucket",\n    "OracleForwardShadowPerformanceReport",\n    "OracleForwardShadowOutcomeEvaluator",\n    "OracleForwardShadowOutcomeEvaluationReport",\n    "OracleForwardShadowHorizonOutcome",\n    "GRADED",\n    "MATURED_NO_OBSERVATION",\n    "WIN",\n    "LOSS",\n    "FLAT",\n    "OracleForwardShadowEvaluationLedger",\n    "OracleForwardShadowLedgerEntry",\n    "OracleForwardShadowLedgerReport",\n    "OracleForwardShadowHorizon",\n    "OracleForwardShadowEvaluationReport",\n    "OracleForwardShadowEvaluationRecord",\n    "OracleForwardShadowEvaluationRecordBuilder",\n    "PENDING",\n    "ADMITTED",\n    "DENIED",\n    "NOT_CANDIDATE",\n    "OracleOpportunityAdmissionGate",\n    "OracleOpportunityAdmissionRecord",\n    "OracleOpportunityAdmissionReport",\n    "CANDIDATE",\n    "EXCLUDED",\n    "MOMENTUM_CONTINUATION",\n    "VOLATILITY_REVERSION_WATCH",\n    "OracleOpportunityCandidateGenerator",\n    "OracleOpportunityCandidateRecord",\n    "OracleOpportunityCandidateReport",\n    "ACCEPTED",\n    "QUARANTINED",\n    "REJECTED",\n    "OracleCorpusMarketSummary",\n    "OracleLiveCorpusInspector",\n    "OracleLiveCorpusReport",\n    "OracleCorpusQualityAnalyzer",\n    "OracleCorpusQualityReport",\n    "OracleMarketQualityRecord",\n    "OracleMarketStatisticsEngine",\n    "OracleMarketStatisticsRecord",\n    "OracleMarketStatisticsReport",\n    "OracleCanonicalMarketFeatureExtractionEngine",\n    "OracleCanonicalMarketFeatureRecord",\n    "OracleCanonicalMarketFeatureReport",\n    "USEFUL",\n    "WATCHLIST",\n    "NOT_USEFUL",\n    "OracleMarketUsefulnessRecord",\n    "OracleMarketUsefulnessReport",\n    "OracleMarketUsefulnessScoringEngine",\n]\n'
TEST = 'from datetime import datetime, timezone\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nimport json\n\nfrom qseries_v2.oracle_intelligence.analytics.oracle_forward_shadow_performance_aggregator import (\n    OracleForwardShadowPerformanceAggregator,\n    stable_hash,\n)\nfrom qseries_v2.oracle_intelligence.analytics.oracle_forward_shadow_outcome_evaluator import stable_hash as outcome_hash\n\nNOW = datetime(2026, 7, 20, 18, 0, 0, tzinfo=timezone.utc)\n\n\ndef write_outcome(root: Path, evaluation_id: str, horizon: int, market: str, family: str, direction: str, grade: str, value: str):\n    body = {\n        "schema_version": "OIA-010", "engine_id": "OIA-010", "evaluated_at": NOW,\n        "evaluation_id": evaluation_id, "market_id": market, "candidate_family": family,\n        "research_direction": direction, "horizon_seconds": horizon, "due_at": NOW,\n        "entry_price_dollars": "0.50", "status": "graded", "grade": grade,\n        "outcome_price_dollars": "0.55", "directional_return": value,\n        "absolute_return": str(abs(float(value))), "observation_sequence_number": 1,\n        "observation_id": "obs-" + evaluation_id, "observation_content_hash": "c" * 64,\n        "observation_observed_at": NOW, "observation_persisted_at": NOW,\n        "observation_delay_seconds": "0", "ledger_entry_hash": "l" * 64,\n        "reason_codes": ["fixed_horizon_outcome_graded"],\n    }\n    payload = dict(body, outcome_hash=outcome_hash(body))\n    path = root / "outcomes" / evaluation_id / f"{horizon}.json"\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, sort_keys=True, indent=2, default=lambda x: x.isoformat()), encoding="utf-8")\n\n\ndef run_test():\n    with TemporaryDirectory() as temporary:\n        root = Path(temporary)\n        outcomes = root / "outcomes_root"\n        performance = root / "performance"\n        write_outcome(outcomes, "e1", 300, "M1", "momentum", "yes", "win", "0.10")\n        write_outcome(outcomes, "e2", 300, "M1", "momentum", "yes", "loss", "-0.04")\n        write_outcome(outcomes, "e3", 900, "M2", "reversion", "no", "flat", "0.00")\n        report = OracleForwardShadowPerformanceAggregator(outcome_directory=outcomes, performance_directory=performance).aggregate(generated_at=NOW)\n        assert report.verified_graded_outcome_count == 3\n        assert report.bucket_count == 9\n        overall = next(bucket for bucket in report.buckets if bucket.dimension == "overall")\n        assert overall.graded_count == 3 and overall.win_count == 1 and overall.loss_count == 1 and overall.flat_count == 1\n        assert overall.win_rate == "0.50000000"\n        assert overall.mean_directional_return == "0.02000000"\n        payload = dict(report.to_dict()); digest = payload.pop("report_hash")\n        assert digest == stable_hash(payload)\n        assert (performance / "current.json").exists()\n        before = sorted(path.read_bytes() for path in (outcomes / "outcomes").glob("*/*.json"))\n        OracleForwardShadowPerformanceAggregator(outcome_directory=outcomes, performance_directory=performance).aggregate(generated_at=NOW)\n        after = sorted(path.read_bytes() for path in (outcomes / "outcomes").glob("*/*.json"))\n        assert before == after\n        assert not report.execution_allowed and not report.source_outcome_mutation_allowed\n    print("[PASS] OIA-011 Oracle Forward Shadow Performance Aggregator")\n\n\nif __name__ == "__main__":\n    run_test()\n'


def main() -> int:
    root = Path.cwd()
    dependency = root / "qseries_v2" / "oracle_intelligence" / "analytics" / "oracle_forward_shadow_outcome_evaluator.py"
    if not dependency.exists():
        raise SystemExit("[FAIL] OIA-010 production module is missing. Install and pass OIA-010 first.")
    text = dependency.read_text(encoding="utf-8")
    required = (
        'SCHEMA_VERSION = "OIA-010"',
        'class OracleForwardShadowOutcomeEvaluator:',
        'class OracleForwardShadowHorizonOutcome:',
        'DEFAULT_OUTCOME_DIRECTORY',
        'outcome_hash',
    )
    missing = [token for token in required if token not in text]
    if missing:
        raise SystemExit(f"[FAIL] Actual OIA-010 contract mismatch: {missing}")

    print("========================================")
    print(" OIA-011 INSTALLER")
    print(" FORWARD SHADOW PERFORMANCE AGGREGATOR")
    print(" DETERMINISTIC RESEARCH SCORECARDS")
    print("========================================")
    print("[OK] Actual OIA-010 outcome contract verified")

    package = root / "qseries_v2" / "oracle_intelligence" / "analytics"
    package.mkdir(parents=True, exist_ok=True)
    targets = (
        (package / "oracle_forward_shadow_performance_aggregator.py", MODULE),
        (package / "__init__.py", INIT),
        (root / "test_oia_011_oracle_forward_shadow_performance_aggregator.py", TEST),
    )
    for path, content in targets:
        path.write_text(content, encoding="utf-8", newline="\n")
        print(f"[OK] FULL REPLACEMENT: {path}")
    for path, content in targets:
        ast.parse(content, filename=str(path))
    print("[OK] OIA-011 production, package, and test syntax verified")

    completed = subprocess.run([sys.executable, str(root / "test_oia_011_oracle_forward_shadow_performance_aggregator.py")], cwd=root)
    if completed.returncode != 0:
        raise SystemExit(completed.returncode)
    print("[OK] OIA-011 test executed successfully")
    print("[DONE] OIA-011 Oracle Forward Shadow Performance Aggregator installed")
    print()
    print("Aggregate live forward-shadow outcomes with:")
    print("python -m qseries_v2.oracle_intelligence.analytics.oracle_forward_shadow_performance_aggregator")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
